import ast, copy, hashlib, importlib.util, itertools, json, random
from pathlib import Path
root=Path('/workspace'); p=json.loads((root/'proposal.json').read_text()); r=json.load(open('/tmp/r001.json'))
base=(root/'history_g3_r0058_fixed_angle_negative.py').read_text()
base_ast=ast.parse(base)
assert (root/'action_full_control.py').read_bytes()==base.encode()
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])

def validate(value,schema):
 typ=schema.get('type')
 if typ=='object':
  assert isinstance(value,dict)
  assert set(schema.get('required',[]))<=set(value)
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{}))
  for k,v in value.items():
   if k in schema.get('properties',{}): validate(v,schema['properties'][k])
 elif typ=='array':
  assert isinstance(value,list) and len(value)>=schema.get('minItems',0)
  for x in value: validate(x,schema['items'])
 elif typ=='string': assert isinstance(value,str) and len(value)>=schema.get('minLength',0)
 if 'const' in schema: assert value==schema['const'] and type(value)==type(schema['const'])
 if 'enum' in schema: assert value in schema['enum']
validate(p['study'],r['study_schema'])

def strip(t,intervened=False):
 t=copy.deepcopy(t)
 if isinstance(t.body[0],ast.Expr) and isinstance(t.body[0].value,ast.Constant): t.body.pop(0)
 if intervened:
  t.body=[n for n in t.body if not (isinstance(n,ast.Assign) and any(isinstance(v,ast.Name) and v.id=='ACTION_PERMUTATION_GROUPS' for v in n.targets))]
  for n in t.body:
   if isinstance(n,ast.ClassDef) and n.name=='Model':
    n.body=[m for m in n.body if not (isinstance(m,ast.FunctionDef) and m.name=='_action_inputs')]
    for m in n.body:
     if isinstance(m,ast.FunctionDef) and m.name=='_represent':
      m.body=[z for z in m.body if not (isinstance(z,ast.Assign) and isinstance(z.value,ast.Call) and isinstance(z.value.func,ast.Attribute) and z.value.func.attr=='_action_inputs')]
 return ast.dump(t,include_attributes=False)
normal=None
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
for v in p['variants']:
 file=root/v['file']; assert file.name==v['file'] and file.suffix=='.py'
 s=file.read_text(); t=ast.parse(s); compile(s,str(file),'exec')
 assert strip(t,file.name"'!='"'action_full_control.py')==strip(base_ast)
 config=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets))
 assert config==v['config']
 for n in ast.walk(t):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  elif isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
 if file.name"'!='"'action_full_control.py':
  q=copy.deepcopy(t)
  for n in q.body:
   if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='ACTION_PERMUTATION_GROUPS' for a in n.targets): n.value=ast.Constant(value='normalized')
  dump=ast.dump(q,include_attributes=False)
  if normal is None: normal=dump
  else: assert normal==dump
 sha=hashlib.sha256(file.read_bytes()).hexdigest(); assert sha in v['note']
 print('PASS syntax/config/hash/inherited-AST/imports:',file.name,sha)

# Pure-Python independent oracle and port of the integer-index construction.
# This validates the algorithm, not torch runtime/device/autograd behavior.
def indexed(action,valid,groups):
 n=len(action); bucket=[g if v else 16 for g,v in zip(groups,valid)]
 order=sorted(range(n),key=lambda i:bucket[i]*n+i)
 rank=[0]*n
 for k,i in enumerate(order):rank[i]=k
 counts=[0]*17
 for b,v in zip(bucket,valid): counts[b]+=int(v)
 starts=[]; total=0
 for count in counts: starts.append(total);total+=count
 result=[]
 for i in range(n):
  b=bucket[i]; count=counts[b]; start=starts[b]
  source=start+(rank[i]-start+count//2)%max(count,1)
  assert 0<=source<n
  result.append(action[order[source]] if valid[i] else action[i])
 return result

def oracle(action,valid,groups):
 result=list(action)
 for g in set(groups):
  idx=[i for i,(v,b) in enumerate(zip(valid,groups)) if v and b==g]
  for k,i in enumerate(idx): result[i]=action[idx[(k+len(idx)//2)%len(idx)]]
 return result

def checks(action,valid,signature):
 for groups in ([0]*len(action),[int(bool(s&14)) for s in signature],signature):
  out=indexed(action,valid,groups)
  assert out==oracle(action,valid,groups)
  assert all(out[i]==action[i] for i,v in enumerate(valid) if not v)
  for g in set(groups):
   ix=[i for i,(v,b) in enumerate(zip(valid,groups)) if v and b==g]
   assert sorted(out[i] for i in ix)==sorted(action[i] for i in ix)
 # Existing all-valid rank rotation exactly.
 idx=[i for i,v in enumerate(valid) if v]; old=list(action)
 for k,i in enumerate(idx):old[i]=action[idx[(k+len(idx)//2)%len(idx)]]
 assert indexed(action,valid,[0]*len(action))==old
 # Signature-determined codes are exact identity (including invalid bytes).
 deterministic=[7*s+1 if v else -999-i for i,(v,s) in enumerate(zip(valid,signature))]
 assert indexed(deterministic,valid,signature)==deterministic

cases=0
for n in range(1,7):
 for pattern in itertools.product([-1,0,1,3,15],repeat=n):
  valid=[s>=0 for s in pattern]; sig=[max(0,s) for s in pattern]
  checks([(i*7)%11 for i in range(n)],valid,sig);cases+=1
rng=random.Random(932)
for _ in range(2000):
 n=100;checks([rng.randrange(19) for _ in range(n)],[bool(rng.randrange(2)) for _ in range(n)],[rng.randrange(16) for _ in range(n)]);cases+=1
print('PASS study schema, proposal constraints, code-group equivalence and',cases,'pure-Python integer invariant cases')
print('Torch available:',importlib.util.find_spec('torch') is not None,'(not imported or executed)')
print('No training, scoring, installation or held-out access performed.')
PY"

